"""Checks that AppTitle names the window of Graphics3D, whether it runs before or after Graphics.

  app_title.py <blitzcc> <app_title.bb> <work directory>

Needs an X display (xvfb-run is fine); the title is read with Xlib through ctypes.
"""
import ctypes
import ctypes.util
import os
import subprocess
import sys
import time
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../tools"))
import procutil  # noqa: E402

blitzcc, source, work = sys.argv[1:4]
os.makedirs(work, exist_ok=True)
exe = os.path.join(work, "app_title" + (".exe" if os.name == "nt" else ""))
procutil.run([blitzcc] + os.environ.get("BLITZCC_OPTIONS", "").split() + [source, "-o", exe], check=True)

x11 = ctypes.CDLL(ctypes.util.find_library("X11"))
x11.XOpenDisplay.restype = ctypes.c_void_p
x11.XOpenDisplay.argtypes = [ctypes.c_char_p]
x11.XDefaultRootWindow.restype = ctypes.c_ulong
x11.XDefaultRootWindow.argtypes = [ctypes.c_void_p]
x11.XFetchName.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(ctypes.c_char_p)]
x11.XQueryTree.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_ulong),
                           ctypes.POINTER(ctypes.POINTER(ctypes.c_ulong)), ctypes.POINTER(ctypes.c_uint)]
display = x11.XOpenDisplay(None)
if not display:
    sys.exit("no X display")


def names(window, out):
    name = ctypes.c_char_p()
    if x11.XFetchName(display, window, ctypes.byref(name)) and name.value:
        out.append(name.value.decode("utf-8", "replace"))
    root, parent, children, count = ctypes.c_ulong(), ctypes.c_ulong(), ctypes.POINTER(ctypes.c_ulong)(), ctypes.c_uint()
    if x11.XQueryTree(display, window, ctypes.byref(root), ctypes.byref(parent), ctypes.byref(children), ctypes.byref(count)):
        for i in range(count.value):
            names(children[i], out)


def check(mode, expected):
    env = dict(os.environ)
    env.pop("BLITZLLVM_HEADLESS", None)
    process = procutil.Popen([exe, mode], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
    if process.stdout.readline().strip() != "started":
        process.kill()
        sys.exit("the program did not start")
    found = []
    for _ in range(50):
        found = []
        names(x11.XDefaultRootWindow(display), found)
        if expected in found:
            break
        time.sleep(0.1)
    process.kill()
    process.communicate(timeout=30)
    if expected not in found:
        sys.exit("AppTitle %s Graphics3D: expected a window titled %r, found %r" % (mode, expected, found))
    print("app title %s ok" % mode)


check("before", "Title before Graphics")
check("after", "Title after Graphics")
